        "text":  "You will need 74 Fletching for Scorching Bow. If you bought Broader Fletching you can make Broad Arrows until 74 which are very fast. Cut Maple Logs while farming Seaweed Spores and then make them Headless + Broad while doing Fishing Trawler for Angler Outfit (Tempoross Combat Achievement).",
